/// The streaming config a chat wire shape declares for every provider that
/// selects it, or `None` when the provider's `stream_config` holds.
pub fn wire_shape_stream_config(chat_wire_shape: &str) -> Option<&'static StreamDef> {
    match chat_wire_shape {
        "ChatResponsesOpenAI" => Some(&StreamDef {
            endpoint: "",
            param: "stream",
            param_value: "true",
            delta_text_path: "delta",
            done_signal: "",
            uses_event_types: true,
            content_event: "response.output_text.delta",
            done_event: "",
            usage_event: "",
            usage_input_path: "usage.input_tokens",
            usage_output_path: "usage.output_tokens",
            usage_opt_in: false,
            final_events: &["response.completed", "response.incomplete"],
            final_body_path: "response",
            error_events: &[
                StreamErrorEventDef {
                    event: "error",
                    code_path: "code",
                    message_path: "message",
                },
                StreamErrorEventDef {
                    event: "response.failed",
                    code_path: "response.error.code",
                    message_path: "response.error.message",
                },
            ],
            retryable_error_codes: &["rate_limit_exceeded", "server_error"],
        }),
        _ => None,
    }
}

